public class PublicVsDeclaredTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String show(java.util.List<String> names) {
        return names == null ? "null" : names.toString();
    }

    public static void main(String[] args) {
        try {
            check("public methods of the base class", "[start]",
                    show(PublicVsDeclared.publicNames(RoadMachine.class)));
            check("declared methods of the base class, every access level",
                    "[audit, inspect, start, tune]",
                    show(PublicVsDeclared.declaredNames(RoadMachine.class)));
            check("a base class inherits nothing public of its own", "[]",
                    show(PublicVsDeclared.inheritedPublicNames(RoadMachine.class)));
            check("public methods of the subclass include the inherited one", "[ring, start]",
                    show(PublicVsDeclared.publicNames(KickScooter.class)));
            check("declared methods of the subclass stop at its own file", "[log, ring]",
                    show(PublicVsDeclared.declaredNames(KickScooter.class)));
            check("the difference between the two lists", "[start]",
                    show(PublicVsDeclared.inheritedPublicNames(KickScooter.class)));
            check("Object's methods are filtered out", false,
                    PublicVsDeclared.publicNames(KickScooter.class).contains("toString"));
            check("a private method never shows up as public", false,
                    PublicVsDeclared.publicNames(KickScooter.class).contains("log"));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected " + t.getClass().getSimpleName() + ": " + t.getMessage());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

