public class PublicVsDeclared {

    public static List<String> publicNames(Class<?> c) {
        TreeSet<String> names = new TreeSet<>();
        for (Method method : c.getMethods()) {
            if (method.getDeclaringClass() != Object.class) {
                names.add(method.getName());
            }
        }
        return new ArrayList<>(names);
    }

    public static List<String> declaredNames(Class<?> c) {
        TreeSet<String> names = new TreeSet<>();
        for (Method method : c.getDeclaredMethods()) {
            names.add(method.getName());
        }
        return new ArrayList<>(names);
    }

    public static List<String> inheritedPublicNames(Class<?> c) {
        List<String> declared = declaredNames(c);
        List<String> result = new ArrayList<>();
        for (String name : publicNames(c)) {
            if (!declared.contains(name)) {
                result.add(name);
            }
        }
        return result;
    }
}
